-- Node: brady-causes (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Reversible Causes of Bradycardic Arrest","body":"Treatable causes of bradycardic arrest:\n\n• **Hyperkalemia** (wide QRS, peaked T): [Calcium Chloride](#/drug/calcium-chloride/hyperkalemia) 1 g IV (preferred in arrest, even peripherally) or [Calcium Gluconate](#/drug/calcium-gluconate/hyperkalemia) 3 g IV + bicarb + insulin/dextrose\n• **Hypothermia**: active rewarming, defer pacing until >30°C (myocardium irritable below 30°C)\n• **Drug toxicity**: beta blocker → [Glucagon](#/drug/glucagon/beta blocker overdose) 3-10mg IV; Ca channel blocker → calcium + high-dose insulin; Digoxin → [DigiFab](#/drug/digifab/digoxin toxicity)\n• **AV block** (complete): temporary pacing bridge → TVP → permanent pacer\n• **Hypoxia**: airway + oxygenation first\n• **Myocardial infarction**: inferior STEMI → right-sided ECG\n\n**Remember:** Treat the cause, not just the rhythm","citation":[2,3,5,10],"next":"brady-cause-check","summary":"HyperK: calcium gluconate 1-3g IV stat — hypothermia: rewarm >30C before pacing","safetyLevel":"critical"}'::jsonb
WHERE id = 'brady-causes' AND tree_id = 'bradycardic-arrest';

-- Node: hd-hyperkalemia-severe (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":2,"title":"Severe Hyperkalemia Protocol","body":"**🚨 SEVERE HYPERKALEMIA — ECG changes present**\n\n**1. CARDIAC MEMBRANE STABILIZATION (Immediate):**\n• **Calcium gluconate 3 g IV** over 10 min\n• Onset: 1-3 minutes\n• Duration: 30-60 minutes\n• May repeat if ECG changes persist\n• Alternative: Calcium chloride 500-1000 mg (central line preferred)\n\n**2. SHIFT K+ INTRACELLULARLY:**\n• **Regular insulin IV — dose by hypoglycemia risk**\n  — Give WITH **25 g dextrose (D50 50 mL)** unless glucose >250 mg/dL\n  — **5 units** (or 0.1 units/kg, max 10) — eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes\n  — **10 units** — normal renal function AND adequate glucose\n  — **Dialysis patients meet the 5-unit criterion → give 5 units**\n  — Onset: 15-30 min, duration 4-6 hr\n  — Check glucose at 30, 60, 120 and 240 min (insulin is renally cleared — hypoglycemia is often delayed)\n• **Albuterol 10-20 mg nebulized** (additive effect)\n  — Onset: 30 min, duration 2 hr\n\n**3. EMERGENT DIALYSIS:**\n• **Call nephrology STAT**\n• Only definitive treatment in ESRD\n• Removes 25-50 mEq K+/hour\n\n**⚠️ NOT emergent therapy:**\n• Kayexalate — hours to work, GI complications\n• Patiromer/SZC — not for acute use","citation":[3,4,18],"next":"hd-electrolyte-disposition","calculatorLinks":[{"id":"hd-hyperkalemia","label":"Hyperkalemia Protocol"}],"summary":"Calcium gluconate 1g IV first, then insulin/dextrose, albuterol neb — emergent dialysis for definitive tx","safetyLevel":"critical"}'::jsonb
WHERE id = 'hd-hyperkalemia-severe' AND tree_id = 'hd-emergencies';

-- Node: hop-metabolic-treatment (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":6,"title":"Pre-Intubation Hyperkalemia Treatment","body":"**Stabilize the membrane and shift K+ BEFORE intubation:**\n\n| Intervention | Dose | Onset | Duration | Mechanism |\n|--------------|------|-------|----------|----------|\n| [Calcium gluconate](#/drug/calcium-gluconate/hyperkalemia) | 3 g IV over 10 min | 1-3 min | 30-60 min | Membrane stabilization |\n| [Calcium chloride](#/drug/calcium-chloride/hyperkalemia) | 1 g IV (central line) | 1-3 min | 30-60 min | 3x more elemental Ca |\n| [Regular insulin](#/drug/insulin-regular/severe hyperkalemia) | 5 units IV (10 units if normal renal function AND adequate glucose) | 15-30 min | 4-6 hours | Intracellular K+ shift |\n| **Dextrose 50%** | 50 mL (25g) IV | -- | -- | Prevent hypoglycemia |\n| [Albuterol](#/drug/albuterol-neb/hyperkalemia) | 10-20 mg nebulized | 15-30 min | 2-4 hours | Intracellular K+ shift |\n\n**Calcium FIRST** - Stabilizes myocardium within minutes while other therapies take effect.\n\n**Insulin dose by hypoglycemia risk** - Give 5 units (or 0.1 units/kg, max 10) if eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes. Give 10 units only with normal renal function AND adequate glucose. Always pair with 25 g dextrose (D50 50 mL) unless glucose >250 mg/dL.\n\n**Check glucose at 30, 60, 120 and 240 min** - hypoglycemia is the main iatrogenic harm.","citation":[8],"next":"hop-metabolic-paralytic","summary":"Calcium, insulin/dextrose, bicarb BEFORE induction if severe hyperkalemia — correct hypocalcemia too","safetyLevel":"critical"}'::jsonb
WHERE id = 'hop-metabolic-treatment' AND tree_id = 'hop-killers';

-- Node: pea-wide (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Wide Complex PEA","body":"**Wide complex PEA — think sodium channel blockade.**\n\n**Common causes:**\n• Hyperkalemia (peaked T waves, sine wave)\n• TCA overdose\n• Sodium channel blocker toxicity (flecainide, procainamide)\n• Severe metabolic acidosis\n• Hypermagnesemia\n\n**Empiric treatment — give immediately:**\n• NaHCO₃ 1-2 mEq/kg IV push\n• [Calcium Chloride](#/drug/calcium-chloride/hyperkalemia) 1 g IV (preferred in arrest, even peripherally) or [Calcium Gluconate](#/drug/calcium-gluconate/hyperkalemia) 3 g IV (equivalent to 1 g calcium chloride)\n• [Lipid Emulsion](#/drug/lipid-emulsion/tca toxicity) if TCA or lipophilic drug suspected\n\n[Wide vs. Narrow PEA](#/info/pea-wide-narrow)","citation":[1,2,10],"next":"pea-causes-wide","images":[{"src":"images/cardiac-arrest/wide-pea-ecg.png","alt":"Wide complex PEA ECG","caption":"Wide QRS >120ms — sodium channel blockade pattern"}],"calculatorLinks":[{"id":"weight-dose","label":"Weight-Based Calculator"}],"summary":"Empiric NaHCO3 1-2 mEq/kg IV push + calcium gluconate 1g IV immediately; lipid emulsion if TCA suspected","safetyLevel":"critical"}'::jsonb
WHERE id = 'pea-wide' AND tree_id = 'pea-arrest';

-- Node: pea-hyperK (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":4,"title":"Hyperkalemia in Arrest","body":"**Hyperkalemia — membrane stabilization + potassium shifting:**\n\n**1. Calcium (membrane stabilizer):**\n• [Calcium Chloride](#/drug/calcium-chloride/hyperkalemia) 1 g IV (preferred in arrest, even peripherally)\n• [Calcium Gluconate](#/drug/calcium-gluconate/hyperkalemia) 3 g IV (equivalent to 1 g calcium chloride; safer in peripheral lines outside arrest)\n\n**2. Insulin + Dextrose (shift K⁺ intracellular):**\n• Regular insulin IV — dose by hypoglycemia risk\n  - **5 units** (or 0.1 units/kg, max 10) — eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes\n  - **10 units** — normal renal function AND adequate glucose\n• D50 50 mL (25 g dextrose) IV with the insulin unless glucose >250 mg/dL\n• Check glucose at 30, 60, 120 and 240 min after the dose\n\n**3. Albuterol (shift K⁺):**\n• 10-20 mg nebulized (continuous)\n\n**4. NaHCO₃ (if acidotic):**\n• 50-100 mEq IV\n\n**Continue high-quality CPR throughout.**","citation":[5,10],"next":"pea-cpr","summary":"Calcium for membrane stabilization, then insulin+D50 and albuterol for K shift, NaHCO3 if acidotic","safetyLevel":"critical"}'::jsonb
