-- Node: rhabdo-hyperkalemia-tx (1 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"result","module":3,"title":"Hyperkalemia Management","body":"**Life-threatening hyperkalemia requires immediate treatment:**\n\n**Cardiac membrane stabilization:**\n• [Calcium gluconate](#/drug/calcium-gluconate/hyperkalemia) 3 g IV over 10 min (preferred) OR\n• [Calcium chloride](#/drug/calcium-chloride/hyperkalemia) 500-1000 mg IV (central line preferred)\n\n**Potassium shifting:**\n• [Regular insulin](#/drug/regular-insulin/hyperkalemia) IV — dose by hypoglycemia risk. Give WITH 25 g dextrose ([D50W](#/drug/dextrose/hyperkalemia) 50 mL) unless glucose >250 mg/dL\n  — **5 units** (or 0.1 units/kg, max 10) — eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes\n  — **10 units** — normal renal function AND adequate glucose\n  — Rhabdomyolysis-associated AKI puts most patients in the 5-unit group\n  — Check glucose at 30, 60, 120 and 240 min\n• [Albuterol](#/drug/albuterol-neb/hyperkalemia) 10-20 mg nebulized\n• [Sodium bicarbonate](#/drug/sodium-bicarbonate/hyperkalemia) 50-100 mEq IV (if acidotic)\n\n**Potassium elimination:**\n• [Furosemide](#/drug/furosemide/hyperkalemia) 40-80 mg IV (if adequate urine output)\n• Dialysis for refractory cases or AKI\n\n**Continuous cardiac monitoring. Recheck K in 1-2 hours.**\n\nSee [Potassium Disorders](#/tree/potassium) for complete management.","citation":[1,6],"recommendation":"Treat hyperkalemia immediately with calcium, insulin/glucose, albuterol. Consider dialysis if refractory or anuric.","treatment":{"firstLine":{"drug":"Calcium gluconate","dose":"1-2 g (10-20 mL of 10%)","route":"IV","frequency":"Over 2-3 min, may repeat","duration":"As needed for cardiac protection","notes":"Cardiac membrane stabilization. Does NOT lower K."},"alternative":{"drug":"Regular insulin + D50W","dose":"Insulin 5 units IV (10 units if normal renal function and adequate glucose) + 25 g dextrose (D50W 50 mL)","route":"IV","frequency":"Once, may repeat","duration":"Effect lasts 4-6 hours","notes":"Shifts K intracellularly. Dose by hypoglycemia risk — 5 units (or 0.1 units/kg, max 10) if eGFR <60, dialysis-dependent, pre-treatment glucose <150 mg/dL, weight <60 kg, or no diabetes (LaRue 2017; Moussavi 2021); 10 units if normal renal function AND adequate glucose (Pierce 2020; UKKA 2023). Check glucose at 30, 60, 120 and 240 min."},"monitoring":"Continuous cardiac monitor. Recheck K in 1-2 hours. Glucose at 30, 60, 120 and 240 min after insulin."},"confidence":"definitive"}'::jsonb
WHERE id = 'rhabdo-hyperkalemia-tx' AND tree_id = 'rhabdomyolysis';

