-- Node: vafei-lidocaine-calc (2 field(s) changed)
UPDATE decision_nodes SET data = '{"type":"info","module":3,"title":"Lidocaine Dose Calculation","body":"**LIDOCAINE TOXICITY PREVENTION:** [3]\n\n**MAXIMUM DOSE: 9 mg/kg lean body weight (DAS ceiling); 7 mg/kg conservative target**\n\n**QUICK CALCULATION (70 kg lean body weight):**\n• 7 mg/kg: max 490 mg\n• 9 mg/kg: max 630 mg\n• 4% lidocaine = 40 mg/mL\n• 490 mg ÷ 40 mg/mL = ~12 mL of 4% (630 mg = ~16 mL)\n\n**TYPICAL DISTRIBUTION:**\n• Nebulizer: 4-5 mL (160-200 mg)\n• Atomizer to pharynx: 3-4 mL (120-160 mg)\n• Through scope to cords: 2-3 mL (80-120 mg)\n• Total: ~9-12 mL (360-480 mg)\n\n**LIDOCAINE TOXICITY SIGNS:**\n• Perioral numbness, metallic taste\n• Tinnitus, visual disturbances\n• Lightheadedness, confusion\n• Seizures, cardiac arrhythmias\n\n**IF TOXICITY SUSPECTED:**\n• Stop lidocaine immediately\n• Support airway/breathing\n• Consider lipid emulsion for severe toxicity","citation":[3],"next":"vafei-sedation","summary":"9 mg/kg LBW max (DAS), 7 mg/kg conservative; 70 kg = ~12 mL (7 mg/kg) to ~16 mL (9 mg/kg) of 4% lidocaine; watch for toxicity signs"}'::jsonb
WHERE id = 'vafei-lidocaine-calc' AND tree_id = 'vafei';

